{
 "title": "交互流程挖掘 · 下单支付",
 "task": "外卖从购物车到支付成功",
 "scope": "2 款外卖 App,2026 年 9 月版本",
 "date": "2026-09-10",
 "summary": "两款 App 的下单链路都是 4 到 5 屏,主要差别在优惠券:快送把选券单独做成一屏,默认不选最优券;小橙在确认订单页直接显示已选最优券,少一屏。",
 "kpis": [
  {
   "key": "products",
   "label": "对比产品",
   "value": 2,
   "unit": "个"
  },
  {
   "key": "screens",
   "label": "分析截图",
   "value": 9,
   "unit": "张"
  },
  {
   "key": "fewest",
   "label": "步骤最少(小橙)",
   "value": 4,
   "unit": "步"
  },
  {
   "key": "issues",
   "label": "发现问题",
   "value": 3,
   "unit": "个"
  }
 ],
 "products": [
  {
   "name": "快送",
   "steps": 5,
   "inputs": 0,
   "verdict": "选券单独一屏,默认不选最优"
  },
  {
   "name": "小橙",
   "steps": 4,
   "inputs": 0,
   "verdict": "最优券直接带入"
  }
 ],
 "chains": [
  {
   "product": "快送",
   "version": "11.2",
   "verdict": "选券单独一屏,默认不选最优",
   "steps": [
    {
     "no": 1,
     "screen": "购物车",
     "content": "菜品、满减进度条",
     "action": "去结算",
     "inputs": 0,
     "note": "满减差额只在进度条末端用小字显示"
    },
    {
     "no": 2,
     "screen": "确认订单",
     "content": "地址、送达时间、金额明细",
     "action": "选择优惠券",
     "inputs": 0,
     "note": ""
    },
    {
     "no": 3,
     "screen": "选择优惠券",
     "content": "可用券列表,默认选第一张",
     "action": "选券并返回",
     "inputs": 0,
     "note": "默认券不是最优券"
    },
    {
     "no": 4,
     "screen": "选择支付方式",
     "content": "支付方式列表,可再次改券",
     "action": "支付",
     "inputs": 0,
     "note": "支付页还能改券,打断支付"
    },
    {
     "no": 5,
     "screen": "支付成功",
     "content": "预计送达时间",
     "action": "完成",
     "inputs": 0,
     "note": ""
    }
   ]
  },
  {
   "product": "小橙",
   "version": "8.9",
   "verdict": "最优券直接带入",
   "steps": [
    {
     "no": 1,
     "screen": "购物车",
     "content": "菜品、还差 X 元满减的提示",
     "action": "去结算",
     "inputs": 0,
     "note": "差额提示在结算按钮上方"
    },
    {
     "no": 2,
     "screen": "确认订单",
     "content": "地址、已选最优券、金额明细",
     "action": "提交订单",
     "inputs": 0,
     "note": "最优券默认选中,可点开更换"
    },
    {
     "no": 3,
     "screen": "选择支付方式",
     "content": "支付方式列表",
     "action": "支付",
     "inputs": 0,
     "note": ""
    },
    {
     "no": 4,
     "screen": "支付成功",
     "content": "预计送达时间、订单入口",
     "action": "完成",
     "inputs": 0,
     "note": ""
    }
   ]
  }
 ],
 "issues": [
  {
   "id": "P1",
   "product": "快送",
   "step": 3,
   "title": "默认不选最优券",
   "severity": "高",
   "evidence": "用户要逐张比较才能找到最优券"
  },
  {
   "id": "P2",
   "product": "快送",
   "step": 1,
   "title": "满减差额提示不明显",
   "severity": "中",
   "evidence": "差额只在进度条末端小字显示"
  },
  {
   "id": "P3",
   "product": "快送",
   "step": 4,
   "title": "支付页可以改券",
   "severity": "低",
   "evidence": "支付前又回到选券,链路变长"
  }
 ],
 "suggestions": [
  {
   "id": "A1",
   "title": "默认选中最优券",
   "detail": "在确认订单页直接显示,需要时再展开更换",
   "basis": [
    "小橙第 2 步",
    "P1"
   ]
  },
  {
   "id": "A2",
   "title": "差额提示放在结算按钮旁",
   "detail": "“再买 6 元减 10 元”,点击可直接加购",
   "basis": [
    "小橙第 1 步",
    "P2"
   ]
  }
 ]
}
